Exactamente. Aquí está el programa completo:

```c
#include <stdio.h>

#define M 5   /* filas: niveles del estadio */
#define N 8   /* columnas: asientos por nivel */

int main(void) {
    int estadio[M][N];
    int buscar, filaEnc = -1, colEnc = -1, encontrado = 0;

    /* --- Lectura --- */
    printf("Ingresa los números de asiento (%d×%d):\n", M, N);
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%d", &estadio[i][j]);
        }
    }

    printf("¿Qué número buscas? ");
    scanf("%d", &buscar);

    /* --- Búsqueda con bandera para salir de ambos ciclos --- */
    for (int i = 0; i < M && !encontrado; i++) {
        for (int j = 0; j < N; j++) {
            if (estadio[i][j] == buscar) {
                filaEnc = i;       /* guardar fila */
                colEnc  = j;       /* guardar columna */
                encontrado = 1;    /* activar bandera */
                break;             /* salir del ciclo interno */
            }                      /* el for externo se detiene por !encontrado */
        }
    }

    /* --- Resultado --- */
    if (encontrado) {
        printf("Encontrado en fila %d, columna %d.\n", filaEnc, colEnc);
    } else {
        printf("El valor %d no está en la matriz.\n", buscar);
    }

    return 0;
}
```

El error frecuente: usar solo `break` dentro del ciclo interno. Ese `break` solo sale de `j`; el ciclo `i` continúa recorriendo filas innecesariamente. La bandera `encontrado` corta ambos ciclos.

**Ejercicio:** modifica el programa para que reporte TODAS las posiciones donde aparece el valor buscado, en caso de que se repita en la matriz.
